function a = myarticulation(nmat);% function a = myarticulation(nmat);% returns the proportion of the time when at least one note% is sounding to the total duration of nmat% Music Therapy Toolboxthres=2;if isempty(nmat) return; enda = 0;o = onset(nmat,'sec');d = dur(nmat,'sec');t = o(end)+d(end);tot = 0;i = size(o,1);while t>0    while or (t < o(i) + d(i), t - o(i) - d(i) > thres)        if (t < o(i) + d(i))            tot = tot + (t - o(i));        end        t = o(i);        i = i-1;        if i == 0            a = a/tot;            return        end    end    a = a + (t - o(i) - d(i));    tot = tot + (t - o(i));    t = o(i);    i = i-1;    if i == 0        a = a/tot;        return    endenda = a/tot;